// Doorway ratio: location-targeted URLs as a share of all indexable URLs. The
// quality classifier averages the entire domain, so a site that is mostly
// location pages is rated as a location-page site whatever else it has.
// Target <= 25%. Pre-cull georgiaautolaw.com was ~85% (1,086 URLs, ~1,000 of
// them doorways). See STEINBERG-MODEL-PLAN §1.1.
//
// Live: the sitemap IS the indexable set. Static (no server, Next.js clients):
// the served-URL enumeration, which reproduces the sitemap from committed content.
import { result, finding } from '../lib/report.mjs';
import { listSiteUrls } from '../lib/site-urls.mjs';

export function classifyPath(p, classify) {
  const segs = p.split('?')[0].split('/').filter(Boolean);
  if (!segs.length) return { isGeo: false, belowFloor: false, hits: [] };
  // The locations section is location-targeted by definition: the state hub
  // (/locations/georgia) counts, every page under it counts; the Spanish index
  // (/es/ubicaciones) is a listing, its children are location pages.
  const underLocations = (segs[0] === 'locations' && segs.length >= 2) || (segs[0] === 'es' && segs[1] === 'ubicaciones' && segs.length >= 3);
  const c = classify(segs[segs.length - 1]);
  return underLocations ? { ...c, isGeo: true } : c;
}

export default {
  id: 'doorway', title: 'Doorway ratio', modes: ['static', 'live'],
  async run(ctx, mode) {
    const r = result(this.id, this.title);
    const max = Number(ctx.args.max) || ctx.cfg.doorwayMaxPct || 25;
    let urls;
    if (mode === 'live') urls = ctx.sitemap.paths.map(u => ({ url: u, geo: classifyPath(u, ctx.geo.classify).isGeo }));
    else {
      if (ctx.framework !== 'nextjs') { r.skipped = true; r.summary.push('skipped: static enumeration needs a Next.js content repo; run with --base'); return r; }
      urls = listSiteUrls(ctx.repo, { classify: ctx.geo.classify, states: ctx.states, locationsPrefix: ctx.cfg.locationsPrefix });
    }
    const geo = urls.filter(u => u.geo);
    const pct = urls.length ? (geo.length / urls.length) * 100 : 0;
    const pass = pct <= max;
    r.stats = { source: mode === 'live' ? 'sitemap' : 'content', total: urls.length, geo: geo.length, pct: Number(pct.toFixed(1)), max, geoUrls: geo.map(u => u.url) };
    r.summary.push(`${mode === 'live' ? 'sitemap' : 'committed content'}: ${urls.length} indexable URLs · ${geo.length} location-targeted · ${pct.toFixed(1)}% (ceiling ${max}%)`);
    if (!pass) finding(r, 'error', `${pct.toFixed(1)}% exceeds the ${max}% ceiling. The classifier averages the whole domain: add substantive non-location pages (research, state law, practice depth) or retire location pages — do NOT add city or city-by-practice pages.`);
    return r;
  },
};
